CustomField.formula:
IF(SBQQ__BillingName__c="Optiv Security Inc (Partner)","Optiv",

  IF(SBQQ__BillingName__c="Hewlett-Packard Enterprise (HPE)","HPE",

    IF(SBQQ__BillingName__c="GuidePoint Security (Partner)","Guidepoint",

      IF(SBQQ__BillingName__c <>  SBQQ__ShippingName__c &&
      ISPICKVAL (Payment_Schedule__c,"UpFront"),"Standard Reseller",

        IF(SBQQ__BillingName__c <>  SBQQ__ShippingName__c &&
        ISPICKVAL (Payment_Schedule__c,"Installments"),"Annualized Reseller","")
)
)
)
)
